1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {aggregateUsage} from './usageAggregation.js';
26	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
27	import {log} from '../shared/logger.js';
28	
29	const DEFAULT_MAX_TOOL_ROUNDS = 5;
30	
31	export interface OrchestratorHooks {
32	  beforeSession?: (session: ChatSession) => Promise<void>;
33	  afterSession?: (session: ChatSession) => Promise<void>;
34	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
35	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
36	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
37	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: UsageMetadata) => Promise<void>;
38	  onError?: (session: ChatSession, error: Error) => Promise<void>;
39	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
40	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
41	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
42	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
43	}
44	
45	export interface ToolBudgetInfo {
46	  maxToolRounds: number;
47	  requestedTools: string[];
48	}
49	
50	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
51	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
52	
53	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
54	
55	export interface ChatOrchestrator {
56	  processMessage(session: ChatSession): Promise<string>;
57	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
58	}
59	
60	export interface ChatOrchestratorOptions {
61	  maxToolRounds?: number;
62	  contextConfig?: Partial<ContextConfig>;
63	  promptBuilderOptions?: PromptBuilderOptions;
64	  hooks?: OrchestratorHooks;
65	  sessionStore?: SessionStore;
66	}
67	
68	interface ToolExecutionResult {
69	  clientMessages: OutgoingMessage[];
70	  suppressOutput: boolean;
71	}
72	export function createChatOrchestrator(
73	  provider: AIProvider,
74	  promptBuilder: PromptBuilder,
75	  toolRegistry?: ToolRegistry,
76	  options?: ChatOrchestratorOptions
77	): ChatOrchestrator {
78	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
79	  const contextConfig = createContextConfig(options?.contextConfig);
80	  const toolInstructions = toolRegistry?.getPromptInstructions();
81	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
82	  const tools = toolRegistry?.getDefinitions();
83	  const hooks = options?.hooks;
84	  const sessionStore = options?.sessionStore;
85	
86	  return {
87	    async processMessage(session: ChatSession): Promise<string> {
88	      return collectText(this.processMessageStream(session));
89	    },
90	
91	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
92	      try {
93	        if (hooks?.beforeSession) await hooks.beforeSession(session);
94	
95	        let userMessage = lastUserContent(session);
96	
97	        if (hooks?.beforeUserInput) {
98	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
99	        }
100	
101	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
102	
103	        const systemPrompt = hooks?.beforeModelResponse
104	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
105	          : baseSystemPrompt;
106	
107	        const messages: Message[] = toMessages(session.entries, contextConfig);
108	        const roundUsages: Array<UsageMetadata | undefined> = [];
109	        let responseText = '';
110	
111	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
112	        for (let round = 0; ; round++) {
113	          log.info('orchestrator', 'starting round', {round});
114	          const pendingToolCalls: ToolCall[] = [];
115	
116	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
117	          responseText += outcome.text;
118	          roundUsages.push(outcome.usage);
119	
120	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
121	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
122	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
123	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
124	            break;
125	          }
126	
127	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
128	          const {clientMessages, suppressOutput} = await executeToolCalls(
129	            pendingToolCalls,
130	            messages,
131	            session,
132	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
133	          );
134	          log.info('orchestrator', 'tool execution complete', {
135	            clientMessageCount: clientMessages.length,
136	            clientMessageTypes: clientMessages.map(m => m.type),
137	            suppressOutput,
138	          });
139	
140	          if (clientMessages.length > 0) {
141	            yield {type: 'tool_result' as const, clientMessages};
142	          }
143	
144	          if (suppressOutput) {
145	            yield {type: 'suppress_output' as const};
146	          }
147	        }
148	
149	        if (hooks?.afterModelResponse)
150	          await hooks.afterModelResponse(session, responseText, aggregateUsage(roundUsages));
151	      } catch (error) {
152	        if (hooks?.onError && error instanceof Error) {
153	          await hooks.onError(session, error);
154	        }
155	        throw error;
156	      } finally {
157	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
158	        commitStreamingEntries(session);
159	        try {
160	          if (hooks?.afterSession) await hooks.afterSession(session);
161	        } finally {
162	          await saveSession(sessionStore, session);
163	        }
164	      }
165	    },
166	  };
167	}
168	
169	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
170	function normalizeToolRounds(value: number | undefined): number {
171	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
172	  return Math.max(0, Math.floor(value));
173	}
174	
175	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
176	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
177	  if (round < maxToolRounds) return false;
178	  log.warn('orchestrator', 'tool budget exhausted', {
179	    maxToolRounds,
180	    requestedTools: pendingToolCalls.map(tc => tc.name),
181	  });
182	  return true;
183	}
184	
185	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
186	async function* closeExhaustedTurn(
187	  session: ChatSession,
188	  budget: ToolBudgetInfo,
189	  hook?: OnToolBudgetExhausted
190	): AsyncGenerator<MessageChunk, string> {
191	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
192	  if (sentence !== '') yield {type: 'text', text: sentence};
193	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
194	  return sentence;
195	}
196	
197	interface RoundOutcome {
198	  stopReason: string;
199	  text: string;
200	  usage?: UsageMetadata;
201	}
202	
203	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
204	async function* streamRound(
205	  provider: AIProvider,
206	  request: SendMessageParams,
207	  pendingToolCalls: ToolCall[]
208	): AsyncGenerator<MessageChunk, RoundOutcome> {
209	  let stopReason = '';
210	  let text = '';
211	  let usage: UsageMetadata | undefined;
212	
