import type {UsageMetadata} from '../types/ai.js';

export function aggregateUsage(usages: Array<UsageMetadata | undefined>): UsageMetadata | undefined {
  const defined = usages.filter((u): u is UsageMetadata => u !== undefined);

  if (defined.length === 0) return undefined;

  return defined.reduce(
    (sum, usage) => ({
      inputTokens: sum.inputTokens + usage.inputTokens,
      outputTokens: sum.outputTokens + usage.outputTokens,
      totalTokens: sum.totalTokens + usage.totalTokens,
    }),
    {inputTokens: 0, outputTokens: 0, totalTokens: 0}
  );
}

